const cfg=window.SITE_CONFIG;
const $=(s)=>document.querySelector(s);
const money=(amount,currency)=>new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:0}).format(amount);
let rates={USD:.0063514,CNY:.042352,EUR:.005677,GBP:.0047584,AUD:.0090417,CAD:.00891,JPY:1},rateDate='2026-10-26';
const colors=['#74adeb','#aa99df','#d293b5','#d7b280','#8ac5ad'];
$('#steps').innerHTML=cfg.steps.map(([title,body],i)=>`<article class="step reveal" style="--step-color:${colors[i]}"><span class="step-number">0${i+1}</span><span class="step-progress"><svg><use href="#${i===4?'check':'arrow-up-right'}"/></svg></span><h3>${title}</h3><p>${body}</p></article>`).join('');
$('#faq-list').innerHTML=cfg.faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('');
const langs=[['cn','中文（简体）','zh'],['sa','العربية','ar'],['nl','Nederlands','nl'],['gb','English','en'],['fr','Français','fr'],['de','Deutsch','de'],['it','Italiano','it'],['pt','Português','pt'],['ru','Русский','ru'],['es','Español','es']];
$('#language-menu').innerHTML=langs.map(([flag,name,code])=>`<button lang="${code}" data-lang="${code}" class="${code==='zh'?'active':''}"><img src="assets/flag-${flag}.svg" alt="">${name}<small>${code==='zh'?'当前':'即将推出'}</small></button>`).join('');
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function contact(type,vehicle=''){
 const value=cfg[type];
 if(value){const url=type==='whatsapp'?`https://wa.me/${value.replace(/\D/g,'')}?text=${encodeURIComponent('您好，我想咨询'+(vehicle||'日本新车出口')+'。')}`:value;window.open(url,'_blank','noopener');return}
 $('#dialog-title').textContent=type==='whatsapp'?'WhatsApp 咨询':'Instagram';$('#dialog-text').textContent=(vehicle?'您想咨询的车型：'+vehicle+'。':'')+'账号尚未开通，请通过邮箱或电话咨询车辆与报价。';$('#contact-dialog').showModal();
}
function renderVehicles(){const curr=$('#currency').value;$('#vehicle-grid').innerHTML=cfg.vehicles.map((v,i)=>`<article class="vehicle-card"><div class="vehicle-image ${i===0?'rx':''}"><img src="${v.image}" alt="${v.name} ${v.imageNote}" loading="lazy"><span>新车</span></div><div class="vehicle-body"><h3>${v.name}</h3><p class="variant">${v.variant}</p><div class="price-row"><small>车辆参考价</small><div class="usd-price">${money(v.priceJPY*rates.USD,'USD')}<small>USD 起</small></div><div class="secondary-prices"><span>${money(v.priceJPY*rates[curr],curr)} ${curr}</span><span>¥${v.priceJPY.toLocaleString('en-US')} JPY</span></div></div><button class="button primary vehicle-consult" data-contact="whatsapp" data-vehicle="${v.name}">立即咨询<svg><use href="#arrow-up-right"/></svg></button></div></article>`).join('');}
function safeGet(k){try{return localStorage.getItem(k)}catch{return null}}function safeSet(k,v){try{localStorage.setItem(k,v)}catch{}}
let currency=safeGet('megumi-currency');if(!currency){let locale=navigator.language||'zh-CN';currency=/^zh/i.test(locale)?'CNY':/^ja/i.test(locale)?'JPY':/GB/i.test(locale)?'GBP':/AU/i.test(locale)?'AUD':/CA/i.test(locale)?'CAD':/^(de|fr|it|es|pt|nl)/i.test(locale)?'EUR':'USD'}
$('#currency').value=currency;renderVehicles();
fetch('rates.json').then(r=>r.ok?r.json():Promise.reject()).then(data=>{rates={...rates,...data.rates};rateDate=data.date;renderVehicles()}).catch(()=>{});
// 第一版仅中文。语言识别与偏好保留，其他语言待内容完成后接入；不进行不必要的 IP 请求。
safeSet('megumi-browser-language',navigator.language||'zh-CN');
$('#currency').addEventListener('change',()=>{const c=$('#currency').value;if(!rates[c]){toast('该货币暂未接入参考汇率，请通过正式报价确认。');$('#currency').value=safeGet('megumi-currency')||currency;return}safeSet('megumi-currency',c);renderVehicles()});
for(const option of $('#currency').options)if(!rates[option.value]){option.disabled=true;option.textContent+='（待接入）'}
const theme=safeGet('megumi-theme')||'dark';document.documentElement.dataset.theme=theme;$('#theme').setAttribute('aria-pressed',theme==='light');$('#theme').addEventListener('click',()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;$('#theme').setAttribute('aria-pressed',t==='light');safeSet('megumi-theme',t)});
$('#language-toggle').addEventListener('click',()=>{const open=$('#language-menu').hidden;$('#language-menu').hidden=!open;$('#language-toggle').setAttribute('aria-expanded',open)});
document.addEventListener('click',e=>{const contactButton=e.target.closest('[data-contact]');if(contactButton)contact(contactButton.dataset.contact,contactButton.dataset.vehicle);const l=e.target.closest('[data-lang]');if(l){toast(l.dataset.lang==='zh'?'当前为中文版。':'该语言版本正在准备中，当前先为您呈现中文内容。');safeSet('megumi-preferred-language',l.dataset.lang);$('#language-menu').hidden=true;$('#language-toggle').setAttribute('aria-expanded','false')}if(!e.target.closest('.language-wrap')){$('#language-menu').hidden=true;$('#language-toggle').setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#language-menu').hidden=true;$('#language-toggle').setAttribute('aria-expanded','false')}});
$('.dialog-close').addEventListener('click',()=>$('#contact-dialog').close());$('#contact-dialog').addEventListener('click',e=>{if(e.target===$('#contact-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.querySelectorAll('#faq-list details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('#faq-list details').forEach(other=>{if(other!==d)other.open=false})}));
const addresses={hq:'日本 千葉県柏市柏3-6-3 FS柏ビル',tokyo:'日本 東京都荒川区西日暮里4-23-2 NOAビル'};
function setMap(key){const q=encodeURIComponent(addresses[key]);$('#map-address').textContent=addresses[key]+(key==='hq'?'4階':'302');$('#map').src=`https://maps.google.com/maps?q=${q}&t=&z=16&ie=UTF8&iwloc=&output=embed`;$('#map').title=`惠澤株式会社${key==='hq'?'本社':'东京营业所'} Google 地图`;$('#map-external').href=`https://www.google.com/maps/search/?api=1&query=${q}`;document.querySelectorAll('[data-map]').forEach(b=>{b.classList.toggle('active',b.dataset.map===key);b.setAttribute('aria-pressed',b.dataset.map===key)})}setMap('hq');document.querySelectorAll('[data-map]').forEach(b=>b.addEventListener('click',()=>setMap(b.dataset.map)));
if('IntersectionObserver' in window){document.documentElement.classList.add('js-ready');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
let ticking=false,previousJourneyProgress=null,reverseLightTimer;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function scrollEffects(){const rect=$('#process').getBoundingClientRect();const progress=Math.min(1,Math.max(0,(innerHeight*.78-rect.top)/(rect.height*.85)));const car=$('.journey-track>svg');const reversing=previousJourneyProgress!==null&&progress<previousJourneyProgress-.0001;const advancing=previousJourneyProgress!==null&&progress>previousJourneyProgress+.0001;car.classList.toggle('reversing',reversing);car.classList.toggle('advancing',advancing);clearTimeout(reverseLightTimer);if(reversing||advancing)reverseLightTimer=setTimeout(()=>{car.classList.remove('reversing');car.classList.remove('advancing')},450);previousJourneyProgress=progress;car.style.left=`calc(${progress*100}% - ${progress*88}px)`;document.querySelectorAll('.step').forEach((el,i)=>el.classList.toggle('current',Math.floor(progress*4.99)===i));ticking=false}if(!reduced){addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(scrollEffects);ticking=true}},{passive:true});scrollEffects()}
const messages=['复杂手续交给我们<br>安心等待车辆交付','按您的预算<br>寻找合适的新车','从日本到目的地<br>全程跟进运输与交付'];let mi=0;if(!reduced)setInterval(()=>{const el=$('#animated-message');el.style.opacity='0';el.style.transform='translateY(7px)';setTimeout(()=>{el.innerHTML=messages[++mi%messages.length];el.style.opacity='1';el.style.transform='none'},400)},5500);
$('#year').textContent=new Date().getFullYear();
